using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers.Api;
[ApiController,Route("api/customers"),Authorize] public class CustomersApiController(ApplicationDbContext db,IAuditService audit):ControllerBase {
 public record CustomerDto(int CustomerId,string CustomerCode,string CustomerName,string Email,string Phone,string? CompanyName,string? City,string Status);
 public record CustomerInput([System.ComponentModel.DataAnnotations.Required]string CustomerName,[System.ComponentModel.DataAnnotations.Required, System.ComponentModel.DataAnnotations.EmailAddress]string Email,[System.ComponentModel.DataAnnotations.Required, System.ComponentModel.DataAnnotations.RegularExpression(@"^[6-9]\d{9}$")]string Phone,string? CompanyName,string? Address,string? City,string? State);
 private IQueryable<Customer> Scope(){var q=db.Customers.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var uid=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value;q=q.Where(x=>x.OwnerId==uid);}return q;}
 [HttpGet] public async Task<IActionResult>Get([FromQuery]string? q){var data=Scope();if(!string.IsNullOrWhiteSpace(q))data=data.Where(x=>x.CustomerName.Contains(q)||x.Email.Contains(q)||x.Phone.Contains(q));return Ok(await data.Select(x=>new CustomerDto(x.CustomerId,x.CustomerCode,x.CustomerName,x.Email,x.Phone,x.CompanyName,x.City,x.Status)).ToListAsync());}
 [HttpGet("{id:int}")]public async Task<IActionResult>GetById(int id){var x=await Scope().FirstOrDefaultAsync(a=>a.CustomerId==id);return x==null?NotFound():Ok(new CustomerDto(x.CustomerId,x.CustomerCode,x.CustomerName,x.Email,x.Phone,x.CompanyName,x.City,x.Status));}
 [HttpPost]public async Task<IActionResult>Create(CustomerInput input){if(await db.Customers.AnyAsync(x=>x.Email==input.Email||x.Phone==input.Phone))return Conflict(new{message="Email or phone already exists."});var x=new Customer{CustomerCode=$"CUS-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}",CustomerName=input.CustomerName,Email=input.Email,Phone=input.Phone,CompanyName=input.CompanyName,Address=input.Address,City=input.City,State=input.State,OwnerId=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value,CreatedBy=User.Identity?.Name};db.Add(x);await db.SaveChangesAsync();await audit.WriteAsync("Create","Customer",x.CustomerId.ToString());return CreatedAtAction(nameof(GetById),new{id=x.CustomerId},new CustomerDto(x.CustomerId,x.CustomerCode,x.CustomerName,x.Email,x.Phone,x.CompanyName,x.City,x.Status));}
 [HttpPut("{id:int}")]public async Task<IActionResult>Update(int id,CustomerInput input){var x=await Scope().FirstOrDefaultAsync(a=>a.CustomerId==id);if(x==null)return NotFound();if(await db.Customers.AnyAsync(a=>a.CustomerId!=id&&(a.Email==input.Email||a.Phone==input.Phone)))return Conflict(new{message="Email or phone already exists."});x.CustomerName=input.CustomerName;x.Email=input.Email;x.Phone=input.Phone;x.CompanyName=input.CompanyName;x.Address=input.Address;x.City=input.City;x.State=input.State;await db.SaveChangesAsync();await audit.WriteAsync("Update","Customer",id.ToString());return NoContent();}
 [HttpDelete("{id:int}")]public async Task<IActionResult>Deactivate(int id){var x=await Scope().FirstOrDefaultAsync(a=>a.CustomerId==id);if(x==null)return NotFound();x.Status="Inactive";await db.SaveChangesAsync();await audit.WriteAsync("Deactivate","Customer",id.ToString());return NoContent();}
}
